def ingest(documents: dict) -> list:
    """Documents -> addressable chunks. Split on paragraph breaks (Ch. 4)."""

def embed(chunks: list, model: MiniLM) -> dict:
    """Chunks -> a searchable index. Vectors are L2-normalised."""

def retrieve(question: str, index: dict, model: MiniLM, k=TOP_K) -> list:
    """Question -> a short list of chunks. SAME model as embed (Ch. 3)."""

def augment(question: str, hits: list, label_chunks=True) -> str:
    """Question + chunks + instruction -> ONE prompt string."""

def generate(prompt: str, use_context=True) -> dict:
    """Prompt -> answer. Deterministic extractive reader — NOT an LLM."""

def retrieve_wrong(question, index, model, k=TOP_K):
    """FAULT (retrieve): a filter bug that skips the gold document."""
    full = retrieve(question, index, model, k=len(index["chunks"]))
    return [h for h in full if h["doc"] != GOLD_DOC][:k]


def trace(label, index, model, *, broken_retrieve=False,
          labels=True, context=True):
    hits   = (retrieve_wrong if broken_retrieve else retrieve)(QUESTION, index, model)
    prompt = augment(QUESTION, hits, label_chunks=labels)
    out    = generate(prompt, use_context=context)
    return {"answer": out["answer"], "cited": out["cited"],
            "grounded": out["grounded"],
            "has_fact": GOLD_FACT in out["answer"]}
